function frame(now: number) {
  requestAnimationFrame(frame);
  tv.poll(now);

  const raw = (now - last) / 1000;
  last = now;

  // Context gone, or the tab is not being composited. Do not simulate, do not
  // draw, do not allocate — just keep the rAF alive so we notice when the world
  // comes back. (A hidden tab on iOS is the single most likely moment for the
  // GPU to reclaim our context, and continuing to queue frames into a surface
  // nobody is presenting is the worst possible way to spend that window.)
  if (suspended || document.hidden || pipeline.contextLost) {
    // The next tick's rAF delta spans however long we were away, which is not a
    // frame interval. Say so, or the ladder reads a backgrounded tab as a stall.
    lastTickPresented = false;
    return;
  }

  // Clamp so a stalled tab or a breakpoint never teleports anything.
  // `__freeze` holds the simulation still while the screenshot harness retries a
  // torn capture: rendering continues, so the compositor can produce a clean
  // frame, but nothing advances — otherwise a retry lands seconds down the road
  // and the shot no longer shows what it was aimed at.
  const frozen = (window as any).__freeze === true;
  const dt = frozen ? 0 : Math.min(raw, 1 / 20);
  ctx.dt = dt;
  ctx.time += dt;
  ctx.frame++;

// race the averages are HELD rather than fed, so the menu's cost never
// reaches them and a second race starts from what the first one learned.
const racing = ctx.race.state === RaceState.Racing;
racingFrames = racing ? racingFrames + 1 : 0;

// The interval only describes a frame the player saw if the tick before it
// also presented, the clock was running, and it is not a tab-switch hole.
const intervalMs = raw * 1000;
const usable = racing && lastTickPresented && !frozen &&
  intervalMs > 1 && intervalMs < 100;
if (usable) {
  frameEma += (intervalMs - frameEma) * FRAME_EMA_ALPHA;
  cleanFrames = intervalMs <= FRAME_CLEAN_MS && frameEma <= FRAME_CLEAN_MS
    ? cleanFrames + 1
    : Math.max(0, cleanFrames - CLEAN_LEAK);
}

if (cost > STALL_MS) {
  stallCount++;
  // Log the first few and then go quiet — a stall storm must not turn into
  // a console-write storm, which is itself a stall.
  if (stallCount <= 5) {
    console.warn(`[frame] ${Math.round(cost)}ms frame; skipping the next present to drain`);
  }
  skipRender = 1;
} else if (ctx.frame <= WATCHDOG_FROM_FRAME) {
  // Boot frames are enormous — shader pre-warm, first-use uploads, the
  // PMREM bake — and they poison the average. Measured: the scaler dropped
  // a rung at frame 9 off a 56ms EMA that was entirely startup cost, on a
  // machine that then ran at 8ms. Hold both averages at the target until the
  // scene has actually settled.
  renderCostEma = 16.7;
  frameEma = 16.7;
  cleanFrames = 0;
} else if (SCALER_PINNED) {
  // See `?scaler=`. The averages above are still maintained, so a pinned run
  // reports the frame cost it is ACTUALLY paying via `__loopHealth`; it just
  // never spends resolution to change it.
} else if (racingFrames < RACING_SETTLE_FRAMES) {
  // Not racing, or not racing for long enough yet. See RACING_SETTLE_FRAMES.
} else if (scaleCooldown > 0) {
  // The cooldown after a step down is also its ASSESSMENT window. When it
  // expires, the rung has to justify itself or it is handed back.
  if (--scaleCooldown === 0) settleDescent();
} else if ((frameEma > FRAME_SLOW_MS || renderCostEma > SLOW_MS) &&
           // See CPU_BOUND_MS. `SLOW_MS` is exempt because at 45ms of
           // submission the loop is running away and the rung is the least
           // of it — dropping is still the right reflex there.
           (renderCostEma < CPU_BOUND_MS || renderCostEma > SLOW_MS) &&
           // See CSS_FLOOR_*. The next rung down may not exist on this
           // device even though the array has one — and it may have been
           // locked out by a descent that bought nothing.

// ---------------------------------------------------------------- countdown

private tickCountdown(ctx: Ctx, dt: number) {
  const prev = Math.ceil(this.countdownT);
  this.countdownT -= dt;
  const now = Math.ceil(this.countdownT);
  // The lead-in beat is not published: the HUD ignores anything above 3, but
  // the audio mix would play a fourth blip of a three-blip metronome, with no
  // numeral on screen to explain it.
  if (now !== prev && now >= 0 && now <= 3) {
    ctx.bus.emit({ type: 'countdown', n: now });
    // The field blips its throttle on every light, not just the last one.
    //
    // `hop` is the ground-puff channel the effects layer already owns, and a
    // puff at each kart's contact patch is the one bit of pre-start energy
    // this system can raise without reaching into anyone else's. Firing it
    // only on "1" meant the grid sat dead through "3" and "2" — three quarters
    // of the countdown, and the exact window the establishing shot is taken
    // in. Three staggered rev blips read as eight running engines waiting for
    // the lights; one puff at the end reads as a car park.
    if (now >= 1) this.revBlip(ctx);
  }
  // Published clamped: the lead-in beat is an implementation detail, and a
  // readout of "5" on the lights would be nonsense.
  this.countdown = clamp(now, 0, 3);
  if (this.countdownT > 0) return;

  this.countdownT = 0;
  this.state = RaceState.Racing;
  this.raceTime = 0;
  // Every kart breaks traction leaving the line, whatever it did with the
  // throttle, so the whole field launches inside a wall of its own dust

el('div', 'kc-title', head, 'Controls');

// The live meter lives in the HEAD, not in a row of its own. On a 390 px
// landscape phone a row is 6% of the frame, and this screen has to fit
// without scrolling — `touch-action: none` on `html` means a child cannot
// re-enable panning however it is styled, so "it scrolls" is not available.
const meter = el('div', 'kc-meter', head);
el('div', 'kc-meter-lab', meter, 'Steer');
const track = el('div', 'kc-meter-track', meter);
el('i', 'kc-meter-mid', track);
this.meterFill = el('b', 'kc-meter-fill', track);
this.meterNum = el('div', 'kc-meter-num', meter, '+0.00');

const done = el('div', 'kc-done', head, 'Done');
done.onclick = () => this.close();

const body = el('div', 'kc-body', this.root);

// --- left column: the four schemes, as cards you can actually read.
const left = el('div', 'kc-schemes', body);
for (const s of SCHEMES) {
  const c = el('div', 'kc-card', left);
  c.innerHTML =
    `<div class="kc-glyph kc-g-${s.glyph}"><i></i><b></b></div>` +
    `<div class="kc-card-t"><em>${s.name}</em><span>${s.blurb}</span></div>`;
  c.onclick = () => this.chooseScheme(s.id);
  this.cards.set(s.id, c);
}

// --- right column: the meter, then the settings.
const right = el('div', 'kc-right', body);

this.tiltRow = el('div', 'kc-tilt', right);
this.tiltVal = el('span', undefined, this.tiltRow, 'waiting for the sensor…');
const re = el('div', 'kc-mini', this.tiltRow, 'Recentre');
re.onclick = () => this.pad?.recentreTilt();

const grid = el('div', 'kc-grid', right);
this.seg<'right' | 'left'>(grid, 'hand', 'Hand', [
  { value: 'right', label: 'Right' }, { value: 'left', label: 'Left' },
], () => this.pad?.prefs.hand, (v) => this.pad?.setHand(v));

this.seg<boolean>(grid, 'auto', 'Throttle', [
  { value: true, label: 'Auto' }, { value: false, label: 'Manual' },
], () => this.pad?.auto, (v) => this.pad?.setAuto(v));

this.seg<number>(grid, 'steerAssist', 'Steering help', [
  { value: 0, label: 'Off' }, { value: 0.35, label: 'Light' }, { value: 0.6, label: 'Strong' },
], () => this.pad?.prefs.steerAssist, (v) => this.pad?.setSteerAssist(v));

this.seg<number>(grid, 'driftAssist', 'Easy drift', [
  { value: 0, label: 'Off' }, { value: 0.5, label: 'Half' }, { value: 1, label: 'Full' },
], () => this.pad?.prefs.driftAssist, (v) => this.pad?.setDriftAssist(v));

this.seg<boolean>(grid, 'haptics', 'Vibration', [
  { value: true, label: 'On' }, { value: false, label: 'Off' },
], () => this.pad?.prefs.haptics, (v) => this.pad?.setHaptics(v));

this.seg<number>(grid, 'tiltRange', 'Tilt range', [
  { value: 20, label: '20°' }, { value: 26, label: '26°' }, { value: 34, label: '34°' },
], () => this.pad?.prefs.tiltRange, (v) => this.pad?.setTiltRange(v));

private readonly loop = (now: number): void => {
  if (this.disposed) return;
  this.rafId = requestAnimationFrame(this.loop);
  if (this.lastTime < 0) this.lastTime = now;
  let dt = (now - this.lastTime) / 1000;
  this.lastTime = now;
  if (dt > MAX_FRAME_DT) dt = MAX_FRAME_DT;
  if (dt < 0) dt = 0;
  this.elapsed += dt;

  const frame = this.tv?.poll();
  const racing = ['countdown','racing','finished'].includes(this.state);
  const input = this.input.update(frame, racing);
  if (['title','characterSelect','trackSelect'].includes(this.state) && input.confirm) this.tvSuspendPending = false;
  try {
    this.frame(dt, input);
  } catch (err) {
    console.error('[Game] frame error', err);
    this.tv?.fail(err);
    events.emit('ui:error', {});
  }
};

private simulate(dt: number, input: InputState): void {
  const r = this.race;
  if (!r) return;
  if (input.useItem) this.pendingUseItem = true;
  this.accumulator += dt;
  let steps = 0;
  while (this.accumulator >= FIXED_DT && steps < MAX_STEPS_PER_FRAME) {
    this.step(FIXED_DT, r, input, this.pendingUseItem);
    this.pendingUseItem = false;
    this.accumulator -= FIXED_DT;
    steps++;
  }
  if (steps >= MAX_STEPS_PER_FRAME) this.accumulator = 0;
}

private step(dt: number, r: RaceContext, input: InputState, useItem: boolean): void {
  const { track, karts, items } = r;
  const player = karts[0];

  // Player input (or auto-drive after finishing).
  if (r.playerAutoDriver) {
    r.playerAutoDriver.update(dt, track, karts, items, null);
  } else {
    const p = this.playerInput;
    p.throttle = input.throttle;
    p.brake = input.brake;
    p.steer = input.steer;
    p.drift = input.drift;
    p.useItem = useItem;
    p.useItemHeld = input.useItemHeld;
    p.lookBack = input.lookBack;
    p.pause = false;
    p.confirm = false;
    p.back = false;
    p.menuUp = false;
    p.menuDown = false;

  if (this.playerTracker) this.playerTracker.throttleStreak = 0;
}

get countdownElapsed(): number { return this.countdownTimer; }

private updateCountdown(dt: number): void {
  // Track how long the player has been holding the throttle (for the start boost).
  if (this.playerTracker) {
    const thr = this.playerTracker.kart.input.throttle;
    this.playerTracker.throttleStreak = thr > 0.5 ? this.playerTracker.throttleStreak + dt : 0;
  }

  this.countdownTimer += dt;
  const total = COUNTDOWN_STEPS * COUNTDOWN_STEP_SECONDS;
  while (this.countdownEmitted < COUNTDOWN_STEPS && this.countdownTimer >= this.countdownEmitted * COUNTDOWN_STEP_SECONDS) {
    events.emit('race:countdown', { count: COUNTDOWN_STEPS - this.countdownEmitted });
    this.countdownEmitted++;
  }
  if (this.countdownTimer >= total) {
    this.go();
  }
}

/** Fixed physics timestep (seconds). Game loop uses an accumulator. */
export const FIXED_DT = 1 / 120;

/** Max frame delta we will simulate in one render frame (avoids spiral of death). */
export const MAX_FRAME_DT = 1 / 20;

update(tv?: TVFrame, racing = true): InputState {
  const s = this.state;
  const now = performance.now();
  const dt = clamp((now - this.lastTime) / 1000, 0, 0.1);
  this.lastTime = now;
  const raw = tv?.buttons || {};
  const held: Partial<Record<TVKey, boolean>> = {};
  for (const key of TV_KEYS) {
    if (!raw[key]) this.tvBlocked[key] = false;
    if (!racing && raw[key]) this.tvBlocked[key] = true;
    held[key] = racing && !!raw[key] && !this.tvBlocked[key] && !tv?.cancelled;
  }

  // --- keyboard --------------------------------------------------------------
  const kbThrottle = this.anyHeld(KEY_THROTTLE) || held.UP ? 1 : 0;
  const kbBrake = this.anyHeld(KEY_BRAKE) || held.DOWN ? 1 : 0;
  const steerTarget = (this.anyHeld(KEY_RIGHT) || held.RIGHT ? 1 : 0) - (this.anyHeld(KEY_LEFT) || held.LEFT ? 1 : 0);
  this.keyboardSteer = rampToward(this.keyboardSteer, steerTarget, dt);

/** m/s^2 at (0.5 + acceleration stat) = 1. Medium kart 0 -> 95% top in ~2.5 s. */
const ACCEL_BASE = 9.0;
/** Proportional approach toward target speed (1/s). */
const ACCEL_APPROACH = 2.2;
/** Acceleration cap / approach while boosting (reaches ~95% of boosted top speed in ~0.3 s). */
const BOOST_ACCEL = 45;
const BOOST_APPROACH = 7;
const OVER_SPEED_DECEL_MAX = 10;
const OVER_SPEED_APPROACH = 2.0;
const BRAKE_DECEL = 16;
const COAST_DECEL = 4.5;
const REVERSE_FRACTION = 0.35;

  const maxAccel = ACCEL_BASE * (0.5 + s.character.stats.acceleration);
  const throttle = s.isBoosting ? 1 : inp.throttle;
  const brake = inp.brake;

  if (brake > 0.05 && speed > 0.3 && brake >= throttle) {
    speed = Math.max(0, speed - BRAKE_DECEL * brake * dt);
  } else if (throttle > 0.05 && throttle >= brake) {
    let target = top * throttle;
    if (s.isDrifting) target *= DRIFT_SPEED_FACTOR;
    if (speed < target) {
      const cap = s.isBoosting ? BOOST_ACCEL : maxAccel;
      const approach = s.isBoosting ? BOOST_APPROACH : ACCEL_APPROACH;
      speed += Math.min(cap, (target - speed) * approach + 0.8) * dt;
      if (speed > target) speed = target;
    } else {
      speed += Math.max(-OVER_SPEED_DECEL_MAX, (target - speed) * OVER_SPEED_APPROACH) * dt;
      if (speed < target) speed = target;
    }
  } else if (brake > 0.05) {
    const target = -REVERSE_FRACTION * top * brake;
    if (speed > target) {
      speed -= Math.min(REVERSE_ACCEL, (speed - target) * 2 + 0.5) * dt;
      if (speed < target) speed = target;
    } else {
      speed += Math.min(6, (target - speed) * 2) * dt;
    }
  } else {
    speed = approachZero(speed, (COAST_DECEL + 0.06 * Math.abs(speed)) * dt);
    if (speed > top) {
      speed += Math.max(-OVER_SPEED_DECEL_MAX, (top - speed) * OVER_SPEED_APPROACH) * dt;
      if (speed < top) speed = top;
    }
  }
  s.speed = speed;
}
